create database customer_shopping_behaviour;

use customer_shopping_behaviour;

select * from customer_shopping limit 30;

# Preaparing few Business Questions using SQL

-- *** Q1. What is the total revenue generated by male vs. female customers?

SELECT gender, SUM(purchase_amount) as total_revenue
FROM customer_shopping
GROUP BY gender;


-- ***Q2. Which customers used a discount but still spent more than the average purchase amount?

select customer_id, purchase_amount
from customer_shopping
where discount_applied = 'Yes'
AND purchase_amount > ( 
select AVG(purchase_amount)
   FROM customer_shopping
  );


-- Q3. Which are the top 5 products with the highest average review rating?

select item_purchased, round(avg(review_rating),2) as avg_rating
from customer_shopping
group by item_purchased 
ORDER BY avg_rating DESC
limit 5;


-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping.

select shipping_type, round(avg(purchase_amount),2) as avg_purchase_amount
from customer_shopping
where shipping_type IN ('Standard','Express')
GROUP BY shipping_type;


-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

select subscription_status, count(customer_id) as total_customer, sum(purchase_amount) as total_revenue, round(avg(purchase_amount),2) as average_spend
from customer_shopping
where subscription_status IN ('Yes','No')	
group by subscription_status
order by total_revenue,average_spend asc;


-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?

select item_purchased, ROUND(AVG(discount_applied = 'Yes')*100,2) as discount_percentage
from customer_shopping
group by item_purchased 
order by discount_percentage desc
limit 5;


-- Q7. Segment customers into New, Returning, and Loyal based previous purchases, and show the count of each segment.

SELECT
    CASE
        WHEN previous_purchases <= 1 THEN 'New'
        WHEN previous_purchases <= 10 THEN 'Returning'
        ELSE 'Loyal'
    END AS customer_segment,
    COUNT(*) AS customer_count
FROM customer_shopping
GROUP BY customer_segment;

-- Q8. What are the top 3 most purchased products within each category?

SELECT category, item_purchased, COUNT(*) AS purchase_count,
DENSE_RANK() OVER (
        PARTITION BY category
        ORDER BY COUNT(*) DESC
        ) AS product_rank
FROM customer_shopping
GROUP BY category, item_purchased
ORDER BY category, purchase_count DESC;


-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

select subscription_status, count( customer_id) as repeat_buyers
from customer_shopping
where subscription_status in ('Yes', 'No') and previous_purchases >5
group by subscription_status;



-- Q10. What is the revenue contribution of each age group?


select age_group, sum(purchase_amount) as total_revenue
from customer_shopping
group by age_group
order by total_revenue desc;